import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const wasmPath = path.resolve(__dirname, "../_build/wasm/release/build/gen/gen.wasm");
const distDir = path.resolve(__dirname, "../dist");

if (!fs.existsSync(distDir)) {
  fs.mkdirSync(distDir, { recursive: true });
}

if (!fs.existsSync(wasmPath)) {
  console.error("❌ feed.wasm not found at:", wasmPath);
  process.exit(1);
}

const wasmBytes = fs.readFileSync(wasmPath);
const targetWasm = path.join(distDir, "feed.wasm");
fs.writeFileSync(targetWasm, wasmBytes);
console.log(`📦 Copied feed.wasm (${(wasmBytes.length / 1024).toFixed(1)} KB) to ${targetWasm}`);

// Also create a tiny index.js wrapper that exports the wasm base64 data URL
// so raw text loaders (?raw) and standard bundlers can load it seamlessly.
const base64 = wasmBytes.toString("base64");
const dataUrl = `data:application/wasm;base64,${base64}`;

const jsContent = `// Auto-generated by bundle-wasm.js from MoonBit build
export const feedWasmBase64 = ${JSON.stringify(dataUrl)};
export default feedWasmBase64;
`;

fs.writeFileSync(path.join(distDir, "index.js"), jsContent);
fs.writeFileSync(path.join(distDir, "index.d.ts"), `export declare const feedWasmBase64: string;\nexport default feedWasmBase64;\n`);
console.log("✅ Wrote dist/index.js and dist/index.d.ts");
